// Some portions generated by Claude

// Renders a Workbench page model into a fake DOM, so the tables of RDF statements on it (the shared
// workbench.queryStream.ResultTable, .agent/execplans/workbench-shared-result-table.md) lay out their rows.
const { FakeDocument } = require('./browser-fakes.js');

function fakeRuntime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, target) { target.template = template; }
    };
}

function memoryRowStore(rows) {
    return {
        async read(start, count) { return rows.slice(start, start + count); },
        async count() { return rows.length; },
        async dispose() {}
    };
}

/** The result-table hosts a rendered template holds, in template order. */
function resultTableHosts(template, found = []) {
    if (Array.isArray(template)) {
        template.forEach(value => resultTableHosts(value, found));
    } else if (template && Array.isArray(template.values)) {
        template.values.forEach(value => resultTableHosts(value, found));
    } else if (template && typeof template.getAttribute === 'function'
            && template.getAttribute('data-workbench-result-table') !== null
            && template.getAttribute('data-workbench-result-table') !== undefined && !found.includes(template)) {
        found.push(template);
    }
    return found;
}

/** Fake DOM as markup: tag, attributes (with the class) and text, for regular-expression assertions. */
function serialize(node) {
    if (!node) {
        return '';
    }
    if (node.nodeType === 3) {
        return node.textContent;
    }
    const tag = String(node.tagName || 'div').toLowerCase();
    const attributes = Array.from(node.attributes ? node.attributes.entries() : [])
        .filter(([name]) => name !== 'class')
        .map(([name, value]) => ` ${name}="${value}"`).join('');
    const className = node.className ? ` class="${node.className}"` : '';
    const content = node.children && node.children.length ? node.children.map(serialize).join('') : node.textContent || '';
    return `<${tag}${className}${attributes}>${content}</${tag}>`;
}

async function settle(rounds = 8) {
    for (let round = 0; round < rounds; round++) {
        await new Promise(resolve => setImmediate(resolve));
    }
}

/**
 * Render model as the page it is (workbench.views.render) into a fake document whose result-table hosts are
 * options.width (default 1200) pixels wide, and wait until the tables have rendered their rows. A model without a
 * row store gets one over model.rows.
 */
async function renderPageResultTables(workbench, model, context, options = {}) {
    const document = new FakeDocument();
    const createElement = document.createElement.bind(document);
    document.createElement = (tagName) => {
        const element = createElement(tagName);
        element.clientWidth = typeof options.width === 'number' ? options.width : 1200;
        return element;
    };
    const mount = createElement('div');
    document.body.appendChild(mount);
    if (!model.rowStore) {
        model.rowStore = memoryRowStore(model.rows || []);
    }
    const runtime = options.runtime || fakeRuntime();
    workbench.views.render(mount, model, context, runtime);
    await settle();
    const outlet = workbench.views.outletOf ? workbench.views.outletOf(mount) : null;
    const template = outlet && outlet.template ? outlet.template : mount.template;
    const hosts = resultTableHosts(template);
    return {
        document,
        mount,
        runtime,
        template,
        hosts,
        host(key) {
            return hosts.find(host => host.getAttribute('data-workbench-result-table') === key) || null;
        },
        markup(key) {
            return (key ? [this.host(key)] : hosts).map(serialize).join('');
        },
        headers(key) {
            const host = this.host(key);
            return host ? host.querySelectorAll('.query-result-table-wrap thead th').map(cell => cell.textContent) : [];
        },
        settle
    };
}

module.exports = {
    fakeRuntime,
    memoryRowStore,
    renderPageResultTables,
    resultTableHosts,
    serialize,
    settle
};
